def transform(grid):
    out = [row[:] for row in grid]
    # A repeated motif has a horizontal bar with a matching two-row stem at
    # its left. Complete the shortest bar by marking its remaining background
    # cells with 1; longer complete examples remain unchanged.
    bg = max(range(10), key=lambda k: sum(v == k for row in grid for v in row))
    bars = []
    for r in range(len(grid) - 2):
        row = grid[r]
        for c, color in enumerate(row):
            if color == bg or (c > 0 and row[c-1] == color):
                continue
            if (grid[r+1][0] == color and grid[r+1][1] == color and
                    grid[r+2][0] == color and grid[r+2][1] == color):
                end = c
                while end + 1 < len(row) and row[end+1] == color:
                    end += 1
                bars.append((end-c+1, r, c, end))
    if bars:
        _, r, start, end = min(bars)
        for c in range(end+1, len(grid[r])):
            if grid[r][c] == bg:
                out[r][c] = 1
    return out

